    for r in range(h):
        if grid[r][0] not in (0, 5):
            for c in range(w):
                if grid[r][c] == 5:
                    out[r][c] = grid[r][0]

    # A vertical 5-bar has a repeating multi-row pattern at its lower end.
    # Tile that seed upward along the bar, preserving the guide itself.
    for c in range(w):
        rail = [r for r in range(h) if grid[r][c] == 5]
        if len(rail) < 3:
            continue
        seeds = []
        for r in range(h):
            vals = []
            x = c + 1
            while x < w and grid[r][x] != 0:
                vals.append(grid[r][x])
                x += 1
            if vals:
                seeds.append((r, vals))
        if seeds:
            seeds.sort()
            patterns = [vals for _, vals in seeds]
            for r in rail:
                vals = patterns[(rail[-1] - r) % len(patterns)]
                for j, value in enumerate(vals):
                    if c + 1 + j < w:
                        out[r][c + 1 + j] = value

